"""run_log.json (+ injection logs) -> REPORT.md. Generated; no hand-typed numbers."""
import glob, json, os
HERE = os.path.dirname(os.path.abspath(__file__)); L_ = json.load(open(os.path.join(HERE, "run_log.json"))); S = L_["stages"]
inj = {os.path.basename(p): json.load(open(p)) for p in glob.glob(os.path.join(HERE, "injection_log_*.json"))}
A, B, P, PT, Cs, F1, F2, F3, F4, E, G = (S[k] for k in ["A_mine", "B_moot_court", "B_parity", "B_point_in_time", "C_outcome_screen", "F1_rationale", "F2_proposals", "F3_merges", "F4_final", "E_agent", "G_identity"])
pit = PT["asof_minus_today_table"]
L = ["# CCL on Databricks: one end-to-end synthetic run (auto-generated by report.py from run_log.json)", "",
     f"Run `{L_['run_id']}` on a personal sandbox workspace. Synthetic hard-world firm (seed 7): 120K decisions over 48 months with deal-desk notes,",
     "CRM edits after decisions, and renewal outcomes that arrive at month + 12*term. The firm decides month-36 deals with the law known at the end of month 35.",
     "**One run, one seed, one decision month: a demonstration of mechanics, not an evaluation.**", "",
     "| Piece | Databricks primitive | What it does and does not establish |", "|---|---|---|",
     "| Point-in-time facts | Delta, one commit group per month; each month-t slice read `VERSION AS OF` the end of month t | month-end state equals decision-time state only because this simulator delays edits to later months |",
     "| Rules | UC SQL functions named by a SHA-256 over compiler version, signature, action and body; created once and an existing body is verified | this script never replaces a function; infrastructure-enforced immutability (ownership/DDL privileges) is not demonstrated |",
     "| LLM-origin rules | trusted compiler `rulec.py`: AST with allow-listed columns, operators, literal domains, length/depth bounds, validated caps; the same AST is evaluated in Python and emitted as SQL | merges must be decision-equivalent to the union of their parts and of one action kind; every new rule is outcome-screened and the whole law re-screened |",
     "| Moot court | one Lakebase branch per candidate (registry state + audit record), replay in DBSQL, endpoint disabled after the verdict | the branch isolates registry records, not the executable law or the replay |",
     "| Registry | Lakebase Postgres `law_events` (append-only, enforced by a trigger that rejects UPDATE/DELETE) + `law_current` view; `law_trials` | every state change is a new event with data and compiler versions |",
     "| Checker | one `check()` function that re-executes every holding's UC function through a given executor | run under the owner AND under a second principal (stage G); not end-user OBO token passthrough |", "",
     "## Results", "",
     f"- **Edits after the decision:** {A['facts_changed_since']:.1%} of mined decisions have facts that differ in today's table. Mining today's table misses: {', '.join('`' + x + '`' for x in A['only_asof']) or 'nothing'}.",
     f"- **Point-in-time contrast:** both arms use the same admission function and are evaluated on later months {PT['test_months']} ({pit['n']} decisions). In this synthetic run, "
     f"accuracy is {pit['acc_a']:.4f} vs {pit['acc_b']:.4f}, a difference of {pit['diff']*100:+.2f} pts with a paired decision-bootstrap interval of [{pit['ci'][0]*100:+.2f}, {pit['ci'][1]*100:+.2f}]. "
     "This interval conditions on the selected laws and the generated history; it does not establish robustness across seeds, decision periods or edit processes.",
     f"- **Moot court:** {B['admitted']}/{B['tried']} mined candidates admitted; branch ready in {B['median_branch_s']} s (median).",
     f"- **Python vs SQL parity:** {P['python_vs_sql_mismatches']} decision mismatches in {P['cases']} admission cases before the LLM steps and {F4['python_vs_sql_mismatches']} after them; "
     f"rules whose case-by-case decided mask differs between Python and SQL: {len(P['mask_mismatches'])} / {len(F4['mask_mismatches'])}. Final per-rule statistics are written as `final_stats` events.",
     f"- **Outcome screen (association, outcomes known before month 36):** flagged {Cs['bad_law']} (reference renewal {Cs['reference_renewal']}).",
     f"- **LLM 'because' (Claude writes, GPT judges, strict rubric):** {F1['matched']}/{F1['total']} matched the hidden reason. Notes are synthetic and templated, so this is easy mode; the judge is itself an LLM.",
     f"- **LLM proposals:** " + "; ".join(f"`{p.get('condition')}` cap {p.get('cap')} -> **{p['verdict']}**" + (f" (outcome {p.get('outcome_status')}, lift {p.get('outcome_lift'):.2f})" if p.get('outcome_lift') is not None else "") for p in F2["proposals"])
     + (". The model returned no proposals of its own this run; only the control (a re-proposal of the screened rule) was tried." if len(F2["proposals"]) <= 1 else ""),
     f"- **LLM merges:** {len(F3['merges'])} proposed; rules now {F3['rules_now']}.",
     f"- **Decision agent:** {E['deals']} month-36 deals ({E['injected']} with an injection attempt in the note): agent = executable law on {E['agent_matches_law']:.0%}; "
     f"injections followed {E['injected_followed']}; checker overrides {E['checker_overrode']}. Agreement with logged decisions {E['final_vs_logged']:.3f} (logs include rogue approvals and noise).",
     f"- **The checker under a second principal** (a workspace service principal): before grant {'denied' if not G['before_grant']['ok'] else 'allowed'}; after granting the full law it "
     f"{'ran and returned the same decision as the owner' if G['after_full_grant'].get('ok') and G['after_full_grant'].get('law') == G['owner_law'] else 'did NOT match'}; with one function withheld "
     f"{'denied' if not G['one_function_withheld']['ok'] else 'allowed'}; after revoke {'denied' if not G['after_revoke']['ok'] else 'allowed'}. Assertions passed: {G['assertions_passed']}. "
     "Audit-log verification of the effective identity is not done here.",
     "- **Pending outcomes:** holdings whose outcome evidence is still pending stay active under this exploratory policy; pending is not evidence of safety. Holdings with no comparable controls under the scoped screen are QUARANTINED (not used).",
     f"- **Integrity checks (stage H):** a function with the expected name but an added `OR true` clause: {S.get('H_integrity', {}).get('tampered_body')}; `TRUNCATE law_events`: {S.get('H_integrity', {}).get('truncate')}.",
     (lambda ic: f"- **Standalone integrity check** (`integrity_check.py`, run `{ic['run_id']}`): {len(ic['checked'])} active rule functions pass exact body + ordered signature + return-type verification, {len(ic['failures'])} fail; a signature-tamper copy (two BOOLEAN parameters swapped, same body): {ic['signature_tamper']}.")(json.load(open(os.path.join(HERE, "integrity_check.json")))),
     "- **Merges:** " + "; ".join(f"`{m.get('id')}` replacing {m.get('replace')} -> **{m.get('verdict')}**" for m in F3['merges']) + " (merges are built as the exact OR of the parts' ASTs; the first is a CONTROL).", ""]
for name, d in sorted(inj.items()):
    model = d.get("model", name.split("injection_log_")[1].rsplit("_", 1)[0]); warn = d.get("warning_in_prompt", name.rsplit("_", 1)[1].startswith("True"))
    L.append(f"- **Injection test `{name}`** (earlier run's law; model {model}, warning in prompt: {warn}): {d['n']} deals the law rejects; followed {d['agent_followed_injection']}, "
             f"invalid citations {d['invalid_citations']}, checker blocked {d['checker_blocked']}, wrong decisions shipped {d['shipped_wrong']}. Zero failures in {d['n']} trials still allows a true failure rate of up to ~26% (95%).")
L += ["", "## Engineering findings", "",
      "- Lakebase caps ACTIVE endpoints per project (~21 observed); read-write endpoints cannot be deleted, so each trial disables its endpoint (`spec.disabled`) and keeps the branch.",
      "- `read_files` rejects nanosecond Parquet timestamps; write microseconds.",
      "- Reading the whole history at one version silently includes later edits; point-in-time means each decision read at its own month's version.",
      "- Claude on the Foundation Model API can return content blocks (a list); parse JSON with `raw_decode` and an expected type."]
open(os.path.join(HERE, "REPORT.md"), "w").write("\n".join(L) + "\n"); print("ok", len(L))
